    return (
        <motion.div 
            ref={ref}
            style={{ opacity }}
            className={`relative flex flex-col md:flex-row gap-8 mb-32 md:mb-48 ${index % 2 === 0 ? 'md:flex-row-reverse' : ''}`}
        >
            {/* Timeline Dot - Lights up when active */}
            <div className="absolute left-[20px] md:left-1/2 top-0 transform -translate-x-1.5 md:-translate-x-1.5 z-20">
                <motion.div 
                    style={{ 
                        boxShadow: glow,
                        backgroundColor: index % 2 === 0 ? '#3b82f6' : '#3b82f6', // Keep accent color
                        scale: useTransform(scrollYProgress, [0, 1], [0.8, 1.2])
                    }}
                    className="w-3 h-3 rounded-full"
                />
            </div>

            {/* Content */}
            <motion.div 
                style={{ x: index % 2 === 0 ? x : useTransform(x, v => -v) }}
                className="pl-12 md:pl-0 md:w-1/2 md:px-16"
            >
                <div className={`${index % 2 === 0 ? 'md:text-left' : 'md:text-right'}`}>
