import React, { useEffect, useRef } from 'react';

const FluidBackground: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const mouseRef = useRef({ x: -1000, y: -1000 });

  useEffect(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let width = 0;
    let height = 0;

    // Grid Configuration
    const spacing = 50;
    const interactionRadius = 200;
    const points: { x: number; y: number; originX: number; originY: number; active: number; glitch: number }[] = [];

    // Resize Handler
    const handleResize = () => {
      width = container.clientWidth;
      height = container.clientHeight;
      canvas.width = width;
      canvas.height = height;

      // Re-initialize points
      points.length = 0;
      const cols = Math.ceil(width / spacing) + 2;
      const rows = Math.ceil(height / spacing) + 2;

      for (let i = -1; i < cols; i++) {
        for (let j = -1; j < rows; j++) {
          const x = i * spacing;
          const y = j * spacing;
          points.push({ 
            x, 
            y, 
            originX: x, 
            originY: y, 
            active: 0,
            glitch: 0
          });
        }
      }
    };

    // Mouse Handler
    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      mouseRef.current = {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top
      };
    };

    window.addEventListener('resize', handleResize);
    window.addEventListener('mousemove', handleMouseMove);

    // Initial setup
    handleResize();

    // Animation Loop
    const render = () => {
      ctx.clearRect(0, 0, width, height);

      const time = Date.now() * 0.001;

      // Draw Connections (only for active points to save perf)
      ctx.beginPath();
      ctx.strokeStyle = '#CCFF00'; // Accent
      ctx.lineWidth = 1; // Thinner lines

      points.forEach((point, i) => {
        // Distance to mouse
        const dx = mouseRef.current.x - point.originX;
        const dy = mouseRef.current.y - point.originY;
        const distance = Math.sqrt(dx * dx + dy * dy);

        // Activate if close to mouse
        const targetActive = distance < interactionRadius ? (1 - distance / interactionRadius) : 0;

        // Smooth transition for activity
        point.active += (targetActive - point.active) * 0.1;

        // Random glitch effect
        if (Math.random() < 0.0005) {
            point.glitch = 30; // 30 frames of glitch
        }
        if (point.glitch > 0) {
            point.glitch--;
        }

        // Slight wave movement for generative feel
        const waveX = Math.sin(time + point.originY * 0.01) * 2;
        const waveY = Math.cos(time + point.originX * 0.01) * 2;
        point.x = point.originX + waveX;
        point.y = point.originY + waveY;

        // Draw Point
        // Base opacity + active boost + glitch boost
        const isActive = point.active > 0.01;
        const isGlitch = point.glitch > 0;

        const size = (isActive || isGlitch) ? 2 : 1;
        const opacity = Math.max(0.1, point.active, isGlitch ? 0.8 : 0);

        ctx.fillStyle = (isActive || isGlitch) ? '#CCFF00' : '#333333';

        // Draw the dot
        ctx.beginPath();
        ctx.arc(point.x, point.y, size, 0, Math.PI * 2);
        ctx.fill();
        ctx.globalAlpha = opacity;
        ctx.fill();
        ctx.globalAlpha = 1.0;

        // Draw Lines
        if (isActive) {
           // Check neighbors (right and bottom) to avoid double drawing
           // Simple proximity check for lines
           points.forEach((otherPoint, j) => {
               if (i === j) return;
               const dist = Math.sqrt((point.x - otherPoint.x) ** 2 + (point.y - otherPoint.y) ** 2);
               if (dist < spacing * 1.5 && otherPoint.active > 0.01) {
                   ctx.beginPath();
                   ctx.moveTo(point.x, point.y);
                   ctx.lineTo(otherPoint.x, otherPoint.y);
                   ctx.strokeStyle = '#CCFF00';
                   ctx.globalAlpha = Math.min(point.active, otherPoint.active) * 0.5;
                   ctx.stroke();
                   ctx.globalAlpha = 1.0;
               }
           });
        }
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div ref={containerRef} className="fixed inset-0 z-0 bg-dark">
      <div className="absolute inset-0 opacity-20 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] brightness-100 contrast-150 mix-blend-overlay pointer-events-none"></div>
      <canvas ref={canvasRef} className="block w-full h-full" />
    </div>
  );
};

export default FluidBackground;

