    if (!canvas || !container) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let width = 0;
    let height = 0;
    let cols = 0;
    let rows = 0;

    // Configuration
    const spacing = 60; // Space between nodes
    const interactionRadius = 300;
    const baseColor = '#1a1a1a'; // Very subtle grey
    const accentColor = '#CCFF00';

    interface Point {
      x: number;
      y: number;
      originX: number;
      originY: number;
      vx: number;
      vy: number;
    }

    let points: Point[] = [];
    let mouse = { x: -1000, y: -1000 };

    const init = () => {
      width = container.clientWidth;
      height = container.clientHeight;
      // Handle high DPI displays
      const dpr = window.devicePixelRatio || 1;
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      ctx.scale(dpr, dpr);

      cols = Math.ceil(width / spacing) + 1;
      rows = Math.ceil(height / spacing) + 1;
      points = [];

      for (let y = 0; y < rows; y++) {
        for (let x = 0; x < cols; x++) {
          points.push({
            x: x * spacing,
            y: y * spacing,
            originX: x * spacing,
            originY: y * spacing,
            vx: 0,
            vy: 0
          });
        }
      }
    };

    const handleResize = () => {
      init();
    };

    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      mouse.x = e.clientX - rect.left;
      mouse.y = e.clientY - rect.top;
    };

    window.addEventListener('resize', handleResize);
    window.addEventListener('mousemove', handleMouseMove);

    init();

    const draw = () => {
      ctx.clearRect(0, 0, width, height);

      const time = Date.now() * 0.001;

      // Update points
      for (let i = 0; i < points.length; i++) {
        const p = points[i];

        // Distance from mouse
        const dx = mouse.x - p.x;
        const dy = mouse.y - p.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        // Interaction force (Repulsion)
        if (dist < interactionRadius) {
          const angle = Math.atan2(dy, dx);
          const force = (interactionRadius - dist) / interactionRadius;
          const repulsion = force * 15; // Repulsion strength

          p.vx += Math.cos(angle) * -repulsion * 0.2;
          p.vy += Math.sin(angle) * -repulsion * 0.2;
        }

        // Gentle floating breath
        const waveX = Math.sin(time + p.originY * 0.02) * 0.5;
        const waveY = Math.cos(time + p.originX * 0.02) * 0.5;

        // Spring back to origin (with wave offset)
        const ox = (p.originX + waveX) - p.x;
        const oy = (p.originY + waveY) - p.y;
        p.vx += ox * 0.05;
        p.vy += oy * 0.05;

        // Friction
        p.vx *= 0.9;
        p.vy *= 0.9;

        p.x += p.vx;
        p.y += p.vy;
      }

      // Draw Grid
      ctx.lineWidth = 1;

      for (let i = 0; i < points.length; i++) {
        const p = points[i];
        const col = i % cols;
        const row = Math.floor(i / cols);

        // Calculate proximity to mouse for styling
        const dx = mouse.x - p.x;
        const dy = mouse.y - p.y;
        const dist = Math.sqrt(dx * dx + dy * dy);
        const isActive = dist < interactionRadius;
        const intensity = isActive ? Math.pow(1 - (dist / interactionRadius), 2) : 0;

        // Draw Connections
        const drawConnection = (p1: Point, p2: Point) => {
            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);

            if (isActive) {
                ctx.strokeStyle = accentColor;
                ctx.globalAlpha = intensity * 0.3; // Faint accent lines
            } else {
                ctx.strokeStyle = baseColor;
                ctx.globalAlpha = 0.05; // Very faint base grid
            }
            ctx.stroke();
            ctx.globalAlpha = 1;
        };

        if (col < cols - 1) drawConnection(p, points[i + 1]); // Right
        if (row < rows - 1) drawConnection(p, points[i + cols]); // Bottom

        // Draw Nodes
        if (isActive && intensity > 0.1) {
             ctx.fillStyle = accentColor;
             const size = intensity * 2;
             ctx.beginPath();
             ctx.arc(p.x, p.y, size, 0, Math.PI * 2);
             ctx.fill();
        } else if (Math.random() > 0.995) {
            // Random faint twinkles for life
             ctx.fillStyle = '#ffffff';
             ctx.globalAlpha = 0.1;
             ctx.beginPath();
             ctx.arc(p.x, p.y, 1, 0, Math.PI * 2);
             ctx.fill();
             ctx.globalAlpha = 1;
        }
      }

      animationFrameId = requestAnimationFrame(draw);
    };

    draw();

    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div ref={containerRef} className="fixed inset-0 z-0 bg-dark pointer-events-none">
      {/* Underlying Noise Texture for texture */}
      <div className="absolute inset-0 opacity-10 bg-[url('https://grainy-gradients.vercel.app/noise.svg')] brightness-100 contrast-150 mix-blend-overlay"></div>

      {/* Geometric Canvas */}
      <canvas ref={canvasRef} className="block w-full h-full" />

      {/* Vignette */}
      <div className="absolute inset-0 bg-radial-gradient from-transparent to-dark/80 pointer-events-none" />
    </div>
  );
};

