import React, { useEffect, useRef } from 'react';

const FluidBackground: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let width = 0;
    let height = 0;

    // Configuration
    const spacing = 40; // Tighter grid for more detail
    const revealRadius = 300; // Size of the "flashlight"
    const accentColor = '204, 255, 0'; // #CCFF00 RGB values

    // State
    const mouse = { x: -1000, y: -1000 };
    let points: { x: number, y: number }[] = [];
    let cols = 0;

    const init = () => {
      width = window.innerWidth;
      height = window.innerHeight;

      // High DPI support for crisp lines
      const dpr = window.devicePixelRatio || 1;
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      ctx.scale(dpr, dpr);
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;

      points = [];
      cols = Math.ceil(width / spacing) + 1;
      const rows = Math.ceil(height / spacing) + 1;

      for (let y = 0; y < rows; y++) {
        for (let x = 0; x < cols; x++) {
          points.push({ x: x * spacing, y: y * spacing });
        }
      }
    };

    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      mouse.x = e.clientX - rect.left;
      mouse.y = e.clientY - rect.top;
    };

    const handleResize = () => init();

    window.addEventListener('resize', handleResize);
    window.addEventListener('mousemove', handleMouseMove);
    init();

    const draw = () => {
      ctx.clearRect(0, 0, width, height);

      points.forEach((p, i) => {
        // Calculate distance from mouse to point
        const dx = mouse.x - p.x;
        const dy = mouse.y - p.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        // Base visibility state (extremely faint structure)
        const isVisible = dist < revealRadius;

        if (isVisible) {
            // Calculate opacity based on distance (cubic ease for smooth falloff)
            const intensity = Math.pow(1 - dist / revealRadius, 3);

            // Draw Point
            ctx.fillStyle = `rgba(${accentColor}, ${intensity})`;
            ctx.fillRect(p.x - 1, p.y - 1, 2, 2);

            // Draw Connections to Neighbors (Right and Bottom)
            const drawConnection = (p2: {x: number, y: number}) => {
                const dx2 = mouse.x - p2.x;
                const dy2 = mouse.y - p2.y;
                const dist2 = Math.sqrt(dx2 * dx2 + dy2 * dy2);

                // Average intensity between two points
                if (dist2 < revealRadius) {
                    const intensity2 = Math.pow(1 - dist2 / revealRadius, 3);
                    const avgIntensity = (intensity + intensity2) / 2;

                    ctx.beginPath();
                    ctx.moveTo(p.x, p.y);
                    ctx.lineTo(p2.x, p2.y);
                    ctx.strokeStyle = `rgba(${accentColor}, ${avgIntensity * 0.4})`; // Lower opacity for lines
                    ctx.lineWidth = 1;
                    ctx.stroke();
                }
            };

            // Connect Right
            if ((i + 1) % cols !== 0 && i + 1 < points.length) {
                drawConnection(points[i + 1]);
            }
            // Connect Bottom
            if (i + cols < points.length) {
                drawConnection(points[i + cols]);
            }

        } else {
             // Optional: Draw extremely faint static grid dots so space isn't completely empty
             // Use very low opacity
             ctx.fillStyle = `rgba(255, 255, 255, 0.03)`;
             ctx.fillRect(p.x - 1, p.y - 1, 2, 2);
        }
      });

      animationFrameId = requestAnimationFrame(draw);
    };

    draw();

    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className="fixed inset-0 z-0 bg-dark pointer-events-none">
      {/* Texture Overlay for analog feel */}
      <div className="absolute inset-0 opacity-[0.05] bg-[url('https://grainy-gradients.vercel.app/noise.svg')] mix-blend-overlay"></div>

      {/* Canvas */}
      <canvas ref={canvasRef} className="block w-full h-full" />

      {/* Vignette to focus attention center/on content */}
      <div className="absolute inset-0 bg-radial-gradient from-transparent to-dark/80 pointer-events-none" />
    </div>
  );
};

