import React, { useEffect, useRef } from 'react';

const FluidBackground: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = window.innerWidth;
    let height = window.innerHeight;
    let animationFrameId: number;
    let time = 0;

    // Grid Configuration
    const spacing = 40; // Distance between points
    const needleLength = 15; // Length of vector lines
    const mouseRadius = 350; // Influence radius in pixels
    const interactionStrength = 0.12; // Lower = smoother/heavier feel

    // State
    // Initialize mouse far away so it doesn't trigger on load
    let mouse = { x: -1000, y: -1000, isActive: false };

    interface Point {
      x: number;
      y: number;
      angle: number; // Current rotation in radians
    }

    let points: Point[] = [];

    const init = () => {
      width = window.innerWidth;
      height = window.innerHeight;

      const dpr = window.devicePixelRatio || 1;
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      ctx.scale(dpr, dpr);
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;

      points = [];
      // Add extra padding to ensure grid covers edges during resize
      const cols = Math.ceil(width / spacing) + 2;
      const rows = Math.ceil(height / spacing) + 2;
      const offsetX = -spacing; 
      const offsetY = -spacing;

      for (let x = 0; x < cols; x++) {
        for (let y = 0; y < rows; y++) {
          points.push({
            x: offsetX + x * spacing,
            y: offsetY + y * spacing,
            angle: 0
          });
        }
      }
    };

    const handleMouseMove = (e: MouseEvent) => {
      const rect = canvas.getBoundingClientRect();
      mouse.x = e.clientX - rect.left;
      mouse.y = e.clientY - rect.top;
      mouse.isActive = true;
    };

    const handleMouseLeave = () => {
      mouse.isActive = false;
    };

    const resizeObserver = new ResizeObserver(() => init());
    resizeObserver.observe(canvas);

    // Use window listener for smoother tracking across elements
    window.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseleave', handleMouseLeave);

    init();

    // Animation Loop
    const draw = () => {
      // Clear with slight transparency if we wanted trails, but clean is better here
      ctx.clearRect(0, 0, width, height);

      time += 0.005; // Speed of idle wave

      points.forEach(point => {
        // Calculate distance to mouse
        const dx = mouse.x - point.x;
        const dy = mouse.y - point.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        let targetAngle = 0;
        let activeScale = 0;

        // Interaction Logic
        if (dist < mouseRadius && mouse.isActive) {
           // Angle towards mouse
           // We add Math.PI to point AWAY, or 0 to point TOWARDS. 
           // Pointing towards looks more like "attraction".
           targetAngle = Math.atan2(dy, dx);

           // Calculate intensity (0 to 1) based on distance
           // Quadratic falloff for smoother edge blending
           activeScale = 1 - Math.pow(dist / mouseRadius, 2); 
           if (activeScale < 0) activeScale = 0;
        } else {
           // Idle Logic: Perlin-ish noise flow field
           // Use coordinates and time to generate a smooth angle
           const scale = 0.0015;
           // Generates values roughly between -PI and PI
           targetAngle = Math.sin(point.x * scale + time) * Math.cos(point.y * scale + time) * 2;
           activeScale = 0;
        }

        // Smooth Rotation (Lerp)
        // Handle angle wrapping (e.g. going from PI to -PI)
        let diff = targetAngle - point.angle;
        // Normalize diff to -PI ... PI
        while (diff < -Math.PI) diff += Math.PI * 2;
        while (diff > Math.PI) diff -= Math.PI * 2;

        point.angle += diff * interactionStrength;

        // Rendering
        ctx.save();
        ctx.translate(point.x, point.y);
        ctx.rotate(point.angle);

        // Visual Style
        const baseAlpha = 0.08;
        // Boost alpha significantly when active
        const alpha = baseAlpha + (activeScale * 0.8);

        ctx.beginPath();
        // Draw centered line
        ctx.moveTo(-needleLength / 2, 0);
        ctx.lineTo(needleLength / 2, 0);

        if (activeScale > 0.01) {
             // Active / Near Cursor -> Acid Green
             // Interpolate color from White to Green based on activeScale
             // Green: 204, 255, 0
             // White: 255, 255, 255
             const r = 255 - (51 * activeScale); // 255 -> 204
             const g = 255;
             const b = 255 - (255 * activeScale); // 255 -> 0

             ctx.strokeStyle = `rgba(${Math.floor(r)}, ${Math.floor(g)}, ${Math.floor(b)}, ${alpha})`;
             ctx.lineWidth = 1 + (activeScale * 1.5); // Slightly thicker
        } else {
             // Idle -> Faint White
             ctx.strokeStyle = `rgba(255, 255, 255, ${alpha})`;
             ctx.lineWidth = 1;
        }

        ctx.stroke();

        // Optional: Draw a tiny pivot dot for "mechanical" feel
        if (activeScale > 0.5) {
             ctx.fillStyle = ctx.strokeStyle;
             ctx.fillRect(-1, -1, 2, 2);
        }

        ctx.restore();
      });

      animationFrameId = requestAnimationFrame(draw);
    };

    draw();

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseleave', handleMouseLeave);
      resizeObserver.disconnect();
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className="fixed inset-0 z-0 bg-dark pointer-events-none">
       {/* Texture Overlay for analog feel */}
       <div className="absolute inset-0 opacity-[0.03] bg-[url('https://grainy-gradients.vercel.app/noise.svg')] mix-blend-overlay"></div>

       {/* Canvas */}
       <canvas ref={canvasRef} className="block w-full h-full" />

       {/* Vignette to focus attention center/on content */}
       <div className="absolute inset-0 bg-radial-gradient from-transparent via-transparent to-black/80 pointer-events-none" />
    </div>
  );
};

export default FluidBackground;

