import React, { useEffect, useState } from 'react';
import { motion, useMotionValue, useSpring } from 'framer-motion';

const CustomCursor: React.FC = () => {
  const [isHovered, setIsHovered] = useState(false);
  const [isClicked, setIsClicked] = useState(false);

  // Mouse position
  const cursorX = useMotionValue(-100);
  const cursorY = useMotionValue(-100);

  // Smooth physics for movement - adjusted for a snappier feel
  const springConfig = { damping: 25, stiffness: 450, mass: 0.5 };
  const smoothX = useSpring(cursorX, springConfig);
  const smoothY = useSpring(cursorY, springConfig);

  useEffect(() => {
    // Check for touch device - if likely touch, don't use custom cursor logic
    const isTouchDevice = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
    if (isTouchDevice) return;

    const moveCursor = (e: MouseEvent) => {
      cursorX.set(e.clientX);
      cursorY.set(e.clientY);
    };

    const handleMouseOver = (e: MouseEvent) => {
      const target = e.target as HTMLElement;
      // Expanded interactive element detection to catch deep nested elements
      const isInteractive = 
        target.tagName === 'A' || 
        target.tagName === 'BUTTON' || 
        target.tagName === 'INPUT' || 
        target.tagName === 'TEXTAREA' || 
        target.tagName === 'LABEL' || 
        target.tagName === 'SELECT' || 
        target.closest('a') || 
        target.closest('button') || 
        target.closest('[role="button"]') || 
        target.closest('.cursor-hover');

      setIsHovered(!!isInteractive);
    };

    const handleMouseDown = () => setIsClicked(true);
    const handleMouseUp = () => setIsClicked(false);

    window.addEventListener('mousemove', moveCursor);
    window.addEventListener('mouseover', handleMouseOver);
    window.addEventListener('mousedown', handleMouseDown);
    window.addEventListener('mouseup', handleMouseUp);

    return () => {
      window.removeEventListener('mousemove', moveCursor);
      window.removeEventListener('mouseover', handleMouseOver);
      window.removeEventListener('mousedown', handleMouseDown);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [cursorX, cursorY]);

  return (
    <motion.div 
        className="fixed top-0 left-0 pointer-events-none z-[9999] mix-blend-difference hidden md:flex items-center justify-center"
        style={{
            x: smoothX,
            y: smoothY,
            translateX: "-50%",
            translateY: "-50%",
        }}
    >
        <motion.div
           className="rounded-full flex items-center justify-center relative"
           animate={{
              width: isHovered ? 80 : 12,
              height: isHovered ? 80 : 12,
              backgroundColor: isHovered ? 'rgba(204, 255, 0, 0.02)' : '#CCFF00', 
              borderColor: '#CCFF00',
              borderWidth: isHovered ? 1 : 0,
              scale: isClicked ? 0.8 : 1,
           }}
           transition={{
              type: "spring",
              stiffness: 300,
              damping: 20,
              mass: 0.8
           }}
        >
             {/* Center Dot - Visible on Hover for precision */}
             <motion.div 
                animate={{ 
                    scale: isHovered ? 1 : 0,
                    opacity: isHovered ? 1 : 0
                }}
                className="w-1.5 h-1.5 bg-accent rounded-full absolute"
            />
        </motion.div>
    </motion.div>
  );
};

export default CustomCursor;

