];

interface MarqueeRowProps {
    direction: 'left' | 'right';
    speed?: number;
    variant?: 'solid' | 'outline';
}

const MarqueeRow: React.FC<MarqueeRowProps> = ({ direction, speed = 20, variant = 'solid' }) => {
  return (
    <div className="flex overflow-hidden relative z-10 select-none py-2">
      <motion.div
        initial={{ x: direction === 'left' ? 0 : "-50%" }}
        animate={{ x: direction === 'left' ? "-50%" : 0 }}
        transition={{ duration: speed, repeat: Infinity, ease: "linear" }}
        className="flex gap-16 md:gap-32 items-center whitespace-nowrap"
      >
        {[...brands, ...brands, ...brands].map((brand, i) => (
          <div key={i} className="group flex items-center gap-16 md:gap-32 cursor-default">
