                    className={`
                        font-display font-bold text-6xl md:text-9xl uppercase tracking-tighter transition-all duration-500 block
                        ${variant === 'solid' 
                            ? 'text-neutral-900 group-hover:text-white' 
                            : 'text-transparent group-hover:text-accent'
                        }
                    `}
                    style={variant === 'outline' ? { WebkitTextStroke: '2px #222' } : {}}
                 >
                    {brand}
                 </span>

                 {/* Glitch Overlay (Visible on Hover) */}
                 <span 
                    className={`
                        absolute inset-0 font-display font-bold text-6xl md:text-9xl uppercase tracking-tighter opacity-0 group-hover:opacity-100 pointer-events-none
                        ${variant === 'solid' ? 'text-white' : 'text-accent'}
