                    {brand}
                 </span>
             </div>

             {/* Separator */}
             <span className="font-mono text-2xl md:text-4xl text-neutral-900 animate-pulse">
                //
             </span>
          </div>
        ))}
      </motion.div>
    </div>
  );
};

const BrandMarquee: React.FC = () => {
