const ProcessStep: React.FC<{ step: typeof steps[0], index: number }> = ({ step, index }) => {
    const ref = useRef<HTMLDivElement>(null);
    const [isHovered, setIsHovered] = useState(false);

    const { scrollYProgress } = useScroll({
        target: ref,
        offset: ["start end", "center center"]
    });

    // Content animations
    const opacity = useTransform(scrollYProgress, [0, 0.5], [0.3, 1]);
    const x = useTransform(scrollYProgress, [0, 1], [50, 0]);

    // Helper for alternating sides
    // We create the negative transform unconditionally to adhere to hook rules
    const negativeX = useTransform(x, (val) => -val);
    const motionX = index % 2 === 0 ? x : negativeX;

    // Dot animations
    const glow = useTransform(scrollYProgress, [0.8, 1], ["0px 0px 0px rgba(204,255,0,0)", "0px 0px 20px rgba(204,255,0,0.5)"]);
    const scale = useTransform(scrollYProgress, [0, 1], [0.8, 1.2]);
    const color = useTransform(scrollYProgress, [0, 1], ["#525252", "#ffffff"]);

    return (
        <motion.div 
            ref={ref}
            style={{ opacity }}
            className={`relative flex flex-col md:flex-row gap-8 mb-24 md:mb-48 ${index % 2 === 0 ? 'md:flex-row-reverse' : ''}`}
        >
            {/* Timeline Dot */}
            <div className="absolute left-[20px] md:left-1/2 top-0 transform -translate-x-1.5 md:-translate-x-1.5 z-20">
                <motion.div 
                    style={{ 
                        boxShadow: glow,
                        backgroundColor: '#CCFF00', 
                        scale: scale
                    }}
                    className="w-3 h-3 rounded-full"
                />
            </div>

            {/* Content Section */}
            <motion.div 
                style={{ x: motionX }}
                className="pl-12 md:pl-0 md:w-1/2 md:px-16"
            >
                <div className={`${index % 2 === 0 ? 'md:text-left' : 'md:text-right'}`}>
                    <motion.span 
                        style={{ color: color }}
                        className="font-display text-4xl md:text-6xl font-bold block mb-4 transition-colors opacity-50"
                    >
                        {step.num}
                    </motion.span>

                    <div 
                        className="relative inline-block"
                        onMouseEnter={() => setIsHovered(true)}
                        onMouseLeave={() => setIsHovered(false)}
                    >
                        <h3 className="text-2xl md:text-3xl font-bold text-white mb-4 font-display uppercase tracking-wider cursor-help transition-colors duration-300 hover:text-accent">
                            {step.title}
                        </h3>

                        <AnimatePresence>
                            {isHovered && (
                                <motion.div
                                    initial={{ opacity: 0, y: 10, scale: 0.9, rotateX: 10 }}
                                    animate={{ opacity: 1, y: 0, scale: 1, rotateX: 0 }}
                                    exit={{ opacity: 0, y: 10, scale: 0.9, rotateX: 10 }}
                                    transition={{ duration: 0.2 }}
                                    className={`absolute bottom-full mb-3 z-50 whitespace-nowrap hidden md:block ${index % 2 === 0 ? 'left-0 origin-bottom-left' : 'right-0 origin-bottom-right'}`}
                                >
                                    <div className="bg-surface/90 backdrop-blur-xl border border-white/10 rounded-xl p-4 shadow-[0_10px_40px_-10px_rgba(0,0,0,0.5)] flex items-center gap-4">
                                        <div className="bg-accent text-black p-2.5 rounded-lg">
                                            <step.icon size={20} strokeWidth={2} />
                                        </div>
                                        <div className="flex flex-col text-left">
                                            <span className="font-mono text-[10px] uppercase text-neutral-500 tracking-wider">Key Focus</span>
                                            <span className="font-bold text-white text-sm tracking-wide">{step.focus}</span>
                                        </div>
                                    </div>
                                    <div className={`absolute top-full w-0 h-0 border-l-[6px] border-l-transparent border-r-[6px] border-r-transparent border-t-[6px] border-t-white/10 ${index % 2 === 0 ? 'left-6' : 'right-6'}`}></div>
                                </motion.div>
                            )}
                        </AnimatePresence>
                    </div>

                    <p className="text-neutral-400 text-base md:text-lg leading-relaxed font-sans">{step.desc}</p>
                </div>
            </motion.div>
            <div className="hidden md:block md:w-1/2" /> 
        </motion.div>
    )
}

