interface CardProps {
    title: string;
    challenge: string;
    solution: string;
    details: string[];
    index: number;
    icon: React.ReactNode;
}

const Card: React.FC<CardProps> = ({ title, challenge, solution, details, index, icon }) => {
    const isDark = index % 2 === 0;
    const bgColor = isDark ? '#0a0a0a' : '#CCFF00';
    const textColor = isDark ? 'white' : 'black';
    const accentColor = isDark ? '#CCFF00' : 'black';
    const mutedColor = isDark ? '#333' : 'rgba(0,0,0,0.2)';

    const listVariants = {
        hidden: { opacity: 0 },
        visible: {
            opacity: 1,
            transition: {
                staggerChildren: 0.1,
                delayChildren: 0.2
            }
        }
    };

    const itemVariants = {
        hidden: { opacity: 0, y: 20, scale: 0.8 },
        visible: { 
            opacity: 0.8, 
            y: 0, 
            scale: 1,
            transition: {
                type: "spring",
                stiffness: 100,
                damping: 10
            }
        }
    };

    return (
        <div className="sticky top-24 md:top-32 mb-12 w-full max-w-5xl mx-auto">
            <div 
                className={`relative overflow-hidden rounded-3xl p-6 md:p-12 border border-white/10 backdrop-blur-md shadow-2xl transition-transform duration-300`}
                style={{ 
                    backgroundColor: bgColor,
                    color: textColor,
                    transform: `rotate(${isDark ? -1 : 1}deg)`
                }}
            >
                {/* Header: Number & Icon */}
                <div className="flex justify-between items-start mb-6 md:mb-8">
                    <span className="font-mono text-xs md:text-sm tracking-widest opacity-60 block pt-3">0{index + 1} // SERVICE</span>
                    <div
                        className="opacity-80 p-2 md:p-3 border border-current rounded-full w-14 h-14 md:w-20 md:h-20 flex items-center justify-center overflow-hidden scale-75 md:scale-100 origin-top-right"
                    >
                        {icon}
                    </div>
                </div>

                {/* Title - Fluid text size for perfect fit */}
                <Reveal>
                    <h2 className="font-display text-[12vw] lg:text-7xl font-bold mb-8 md:mb-12 leading-[0.9]">{title}</h2>
                </Reveal>

                {/* Challenge & Solution Grid */}
                <div className="grid grid-cols-1 md:grid-cols-2 gap-8 md:gap-12 mb-8 md:mb-12">
                    <div>
                        <Reveal delay={0.1}>
                            <h3 className="font-mono text-[10px] md:text-xs uppercase tracking-widest mb-2 md:mb-4 opacity-70 flex items-center gap-2">
                               <span className="w-2 h-2 rounded-full" style={{ backgroundColor: mutedColor }}></span>
                               The Challenge
                            </h3>
                        </Reveal>
                        <StaggeredWordReveal text={challenge} className="text-base md:text-xl font-medium leading-relaxed opacity-90" delay={0.2} />
                    </div>
                    <div>
                         <Reveal delay={0.3}>
                             <h3 className="font-mono text-[10px] md:text-xs uppercase tracking-widest mb-2 md:mb-4 opacity-70 flex items-center gap-2">
                               <span className="w-2 h-2 rounded-full" style={{ backgroundColor: accentColor }}></span>
                               The Bold Solution
                            </h3>
                        </Reveal>
                        <StaggeredWordReveal text={solution} className="text-base md:text-xl font-medium leading-relaxed opacity-90" delay={0.4} />
                    </div>
                </div>

                {/* Footer: Details */}
                <div className="border-t border-current/20 pt-6 md:pt-8">
                    <motion.ul 
                        variants={listVariants}
                        initial="hidden"
                        whileInView="visible"
                        viewport={{ once: false, margin: "-10%" }}
                        className="flex flex-wrap gap-x-4 gap-y-2 md:gap-x-8 md:gap-y-4"
                    >
                        {details.map((d, i) => (
                            <motion.li 
                                key={i} 
                                variants={itemVariants}
                                whileHover={{ scale: 1.1, opacity: 1, x: 5, transition: { type: "spring", stiffness: 300 } }}
                                className="font-mono text-[10px] md:text-sm uppercase tracking-wider flex items-center gap-2 cursor-default"
                            >
                                <span className={`w-1 h-1 md:w-1.5 md:h-1.5 rounded-full`} style={{ backgroundColor: accentColor }} />
                                {d}
                            </motion.li>
                        ))}
                    </motion.ul>
                </div>
            </div>
        </div>
    )
}

