import React, { useEffect, useRef } from 'react';

const FluidBackground: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = window.innerWidth;
    let height = window.innerHeight;
    let animationFrameId: number;
    let time = 0;

    // Configuration
    const spacing = 60; // Grid density
    const mouseRadius = 300; // Cursor influence
    const connectionLimit = 85; // Distance at which nodes connect
    const accentColor = '#CCFF00';
    const baseColor = 'rgba(255, 255, 255, 0.1)';

    let mouse = { x: -1000, y: -1000, active: false };

    interface Node {
      x: number;
      y: number;
      baseX: number;
      baseY: number;
      vx: number;
      vy: number;
      active: number; // 0 to 1 intensity
    }

    let nodes: Node[] = [];

    const init = () => {
      width = window.innerWidth;
      height = window.innerHeight;

      const dpr = window.devicePixelRatio || 1;
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      ctx.scale(dpr, dpr);
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;

      nodes = [];
      const cols = Math.ceil(width / spacing) + 1;
      const rows = Math.ceil(height / spacing) + 1;

      for (let i = 0; i < cols; i++) {
        for (let j = 0; j < rows; j++) {
          const x = i * spacing;
          const y = j * spacing;
          nodes.push({
            x,
            y,
            baseX: x,
            baseY: y,
            vx: 0,
            vy: 0,
            active: 0
          });
        }
      }
    };

    const handleMouseMove = (e: MouseEvent) => {
      mouse.x = e.clientX;
      mouse.y = e.clientY;
      mouse.active = true;
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('resize', init);

    init();

    const draw = () => {
      ctx.clearRect(0, 0, width, height);
      time += 0.01;

      // Update nodes
      nodes.forEach(node => {
        // Subtle drift
        const driftX = Math.sin(time + node.baseX * 0.01) * 5;
        const driftY = Math.cos(time + node.baseY * 0.01) * 5;

        const targetX = node.baseX + driftX;
        const targetY = node.baseY + driftY;

        // Mouse interaction
        const dx = mouse.x - node.x;
        const dy = mouse.y - node.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist < mouseRadius && mouse.active) {
          const force = (mouseRadius - dist) / mouseRadius;
          // Magnetic pull
          node.vx += dx * force * 0.03;
          node.vy += dy * force * 0.03;
          node.active = Math.min(node.active + 0.1, force);
        } else {
          node.active *= 0.92; // Fade out activity
        }

        // Apply physics
        node.x += node.vx;
        node.y += node.vy;

        // Return to base position spring
        node.vx += (targetX - node.x) * 0.05;
        node.vy += (targetY - node.y) * 0.05;

        // Friction
        node.vx *= 0.85;
        node.vy *= 0.85;
      });

      // Draw connections
      ctx.lineWidth = 0.5;
      for (let i = 0; i < nodes.length; i++) {
        const nodeA = nodes[i];

        // Only check neighboring nodes to keep performance high
        for (let j = i + 1; j < nodes.length; j++) {
          const nodeB = nodes[j];
          const dx = nodeA.x - nodeB.x;
          const dy = nodeA.y - nodeB.y;
          const distSq = dx * dx + dy * dy;

          if (distSq < connectionLimit * connectionLimit) {
            const dist = Math.sqrt(distSq);
            const opacity = 1 - (dist / connectionLimit);
            const activeMix = Math.max(nodeA.active, nodeB.active);

            ctx.beginPath();
            ctx.moveTo(nodeA.x, nodeA.y);
            ctx.lineTo(nodeB.x, nodeB.y);

            if (activeMix > 0.1) {
              // Blend to accent color at intersections near cursor
              ctx.strokeStyle = `rgba(204, 255, 0, ${opacity * activeMix * 0.5})`;
            } else {
              ctx.strokeStyle = `rgba(255, 255, 255, ${opacity * 0.1})`;
            }
            ctx.stroke();
          }
        }
      }

      // Draw nodes (intersections)
      nodes.forEach(node => {
        if (node.active > 0.01) {
          const size = 1.5 + (node.active * 2);

          // Outer glow for active nodes
          ctx.beginPath();
          ctx.arc(node.x, node.y, size * 3, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(204, 255, 0, ${node.active * 0.15})`;
          ctx.fill();

          // Core node
          ctx.beginPath();
          ctx.arc(node.x, node.y, size, 0, Math.PI * 2);
          ctx.fillStyle = accentColor;
          ctx.fill();
        } else {
          // Subtle base nodes
          ctx.fillStyle = 'rgba(255, 255, 255, 0.05)';
          ctx.fillRect(node.x - 0.5, node.y - 0.5, 1, 1);
        }
      });

      animationFrameId = requestAnimationFrame(draw);
    };

    draw();

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('resize', init);
      cancelAnimationFrame(animationFrameId);
    };
