import React, { useEffect, useRef } from 'react';

const FluidBackground: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = window.innerWidth;
    let height = window.innerHeight;
    let animationFrameId: number;
    let time = 0;

    // Configuration
    const spacing = 75; // Grid density (higher = fewer nodes, better performance)
    const mouseRadius = 250; // Cursor influence radius
    const connectionLimit = 110; // Max distance for connection lines
    const accentColor = '#CCFF00';

    let mouse = { x: -1000, y: -1000, active: false };

    interface Node {
      x: number;
      y: number;
      baseX: number;
      baseY: number;
      vx: number;
      vy: number;
      active: number; // 0 (dormant) to 1 (fully active near cursor)
      phase: number;
    }

    let nodes: Node[] = [];

    const init = () => {
      width = window.innerWidth;
      height = window.innerHeight;

      const dpr = window.devicePixelRatio || 1;
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      ctx.scale(dpr, dpr);
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;

      nodes = [];
      const cols = Math.ceil(width / spacing) + 1;
      const rows = Math.ceil(height / spacing) + 1;

      for (let i = 0; i < cols; i++) {
        for (let j = 0; j < rows; j++) {
          // Initialize with slight randomness from the grid
          const x = i * spacing + (Math.random() - 0.5) * spacing * 0.4;
          const y = j * spacing + (Math.random() - 0.5) * spacing * 0.4;
          nodes.push({
            x,
            y,
            baseX: x,
            baseY: y,
            vx: 0,
            vy: 0,
            active: 0,
            phase: Math.random() * Math.PI * 2
          });
        }
      }
    };

    const handleMouseMove = (e: MouseEvent) => {
      mouse.x = e.clientX;
      mouse.y = e.clientY;
      mouse.active = true;
    };

    const handleMouseLeave = () => {
      mouse.active = false;
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseleave', handleMouseLeave);
    window.addEventListener('resize', init);

    init();

    const draw = () => {
      ctx.clearRect(0, 0, width, height);
      time += 0.004;

      // 1. Update positions and activity levels
      for (const node of nodes) {
        // Organic generative drift
        const driftX = Math.sin(time + node.phase) * 12;
        const driftY = Math.cos(time + node.phase * 0.8) * 12;

        const targetX = node.baseX + driftX;
        const targetY = node.baseY + driftY;

        // Interactive behavior
        if (mouse.active) {
          const dx = mouse.x - node.x;
          const dy = mouse.y - node.y;
          const distSq = dx * dx + dy * dy;
          const dist = Math.sqrt(distSq);

          if (dist < mouseRadius) {
            const force = (mouseRadius - dist) / mouseRadius;
            // Magnetic distortion
            node.vx += dx * force * 0.02;
            node.vy += dy * force * 0.02;
            // Activate node color and size
            node.active = Math.min(1, node.active + force * 0.15);
          } else {
            node.active *= 0.94;
          }
        } else {
          node.active *= 0.94;
        }

        // Apply physics
        node.x += node.vx;
        node.y += node.vy;

        // Return to base position (elasticity)
        node.vx += (targetX - node.x) * 0.04;
        node.vy += (targetY - node.y) * 0.04;

        // Damping
        node.vx *= 0.88;
        node.vy *= 0.88;
      }

      // 2. Draw Connection Matrix
      ctx.lineWidth = 0.5;
      for (let i = 0; i < nodes.length; i++) {
        const nodeA = nodes[i];

        for (let j = i + 1; j < nodes.length; j++) {
          const nodeB = nodes[j];
          const dx = nodeA.x - nodeB.x;
          const dy = nodeA.y - nodeB.y;
          const distSq = dx * dx + dy * dy;

          if (distSq < connectionLimit * connectionLimit) {
            const dist = Math.sqrt(distSq);
            const opacity = (1 - dist / connectionLimit) * 0.12;
            const activity = Math.max(nodeA.active, nodeB.active);

            ctx.beginPath();
            ctx.moveTo(nodeA.x, nodeA.y);
            ctx.lineTo(nodeB.x, nodeB.y);

            if (activity > 0.1) {
              // Highlighted connection near cursor
              ctx.strokeStyle = `rgba(204, 255, 0, ${opacity * activity * 3})`;
            } else {
              // Subtle background connection
              ctx.strokeStyle = `rgba(255, 255, 255, ${opacity})`;
            }
            ctx.stroke();
          }
        }
      }

      // 3. Draw Intersection Nodes
      for (const node of nodes) {
        if (node.active > 0.02) {
          // Highlighted Node (Intersection)
          const size = 1.2 + node.active * 1.8;

          // Glow effect
          ctx.beginPath();
          ctx.arc(node.x, node.y, size * 5, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(204, 255, 0, ${node.active * 0.12})`;
          ctx.fill();

          // Core dot
          ctx.beginPath();
          ctx.arc(node.x, node.y, size, 0, Math.PI * 2);
          ctx.fillStyle = accentColor;
          ctx.fill();
        } else {
          // Minimal Base Node
          ctx.fillStyle = 'rgba(255, 255, 255, 0.06)';
          ctx.beginPath();
          ctx.arc(node.x, node.y, 0.8, 0, Math.PI * 2);
          ctx.fill();
        }
      }

      animationFrameId = requestAnimationFrame(draw);
    };

    draw();

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseleave', handleMouseLeave);
      window.removeEventListener('resize', init);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className="fixed inset-0 z-0 bg-dark pointer-events-none">
       {/* High-frequency noise overlay */}
       <div className="absolute inset-0 opacity-[0.03] bg-[url('https://grainy-gradients.vercel.app/noise.svg')] mix-blend-overlay"></div>

       <canvas ref={canvasRef} className="block w-full h-full" />

       {/* Ambient Depth Gradients */}
       <div className="absolute inset-0 bg-gradient-to-t from-dark via-transparent to-dark/60 pointer-events-none" />
       <div className="absolute inset-0 bg-[radial-gradient(circle_at_center,transparent_0%,rgba(5,5,5,0.3)_100%)] pointer-events-none" />
    </div>
  );
};

