import React, { useEffect, useRef } from 'react';

const FluidBackground: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = window.innerWidth;
    let height = window.innerHeight;
    let animationFrameId: number;
    let time = 0;

    // High Interaction Configuration
    const spacing = 55; // Denser grid for more detail
    const mouseRadius = 350; // Larger influence area
    const connectionLimit = 100; 
    const accentColor = '#CCFF00';

    let mouse = { x: -1000, y: -1000, active: false };

    interface Node {
      x: number;
      y: number;
      baseX: number;
      baseY: number;
      vx: number;
      vy: number;
      active: number; 
      phase: number;
    }

    let nodes: Node[] = [];

    const init = () => {
      width = window.innerWidth;
      height = window.innerHeight;

      const dpr = window.devicePixelRatio || 1;
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      ctx.scale(dpr, dpr);
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;

      nodes = [];
      const cols = Math.ceil(width / spacing) + 1;
      const rows = Math.ceil(height / spacing) + 1;

      for (let i = 0; i < cols; i++) {
        for (let j = 0; j < rows; j++) {
          const x = i * spacing;
          const y = j * spacing;
          nodes.push({
            x,
            y,
            baseX: x,
            baseY: y,
            vx: 0,
            vy: 0,
            active: 0,
            phase: Math.random() * Math.PI * 2
          });
        }
      }
    };

    const handleMouseMove = (e: MouseEvent) => {
      mouse.x = e.clientX;
      mouse.y = e.clientY;
      mouse.active = true;
    };

    const handleMouseLeave = () => {
      mouse.active = false;
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseleave', handleMouseLeave);
    window.addEventListener('resize', init);

    init();

    const draw = () => {
      ctx.clearRect(0, 0, width, height);
      time += 0.005;

      // 1. Physics Update
      for (const node of nodes) {
        // Base generative movement (breathing)
        const driftX = Math.sin(time + node.phase) * 2;
        const driftY = Math.cos(time + node.phase) * 2;

        const targetX = node.baseX + driftX;
        const targetY = node.baseY + driftY;

        // Interaction
        if (mouse.active) {
          const dx = mouse.x - node.x;
          const dy = mouse.y - node.y;
          const distSq = dx * dx + dy * dy;

          if (distSq < mouseRadius * mouseRadius) {
            const dist = Math.sqrt(distSq);
            const force = (mouseRadius - dist) / mouseRadius;

            // Strong Magnetic Pull
            const angle = Math.atan2(dy, dx);
            const pullStrength = force * 2; // Increased pull

            node.vx += Math.cos(angle) * pullStrength;
            node.vy += Math.sin(angle) * pullStrength;

            // Rapid activation
            node.active = Math.min(1, node.active + 0.2);
          } else {
            node.active *= 0.9;
          }
        } else {
          node.active *= 0.9;
        }

        // Apply velocities
        node.x += node.vx;
        node.y += node.vy;

        // Spring back to base (elasticity)
        const springStrength = 0.08; // Snappy return
        node.vx += (targetX - node.x) * springStrength;
        node.vy += (targetY - node.y) * springStrength;

        // Friction/Damping
        node.vx *= 0.85; // Less friction = more movement
        node.vy *= 0.85;
      }

      // 2. Render Connections
      ctx.lineWidth = 0.5;
      for (let i = 0; i < nodes.length; i++) {
        const nodeA = nodes[i];

        // Optimization: check grid proximity first or just limit loops? 
        // With 75 spacing, n is small enough for brute force neighbor check on modern devices, 
        // but let's optimize slightly by checking only nearby indices if we were strictly grid based.
        // For now, distance check is fast enough for < 1000 nodes.

        for (let j = i + 1; j < nodes.length; j++) {
          const nodeB = nodes[j];
          const dx = nodeA.x - nodeB.x;
          const dy = nodeA.y - nodeB.y;
          const distSq = dx * dx + dy * dy;

          if (distSq < connectionLimit * connectionLimit) {
            const opacity = 1 - (Math.sqrt(distSq) / connectionLimit);
            const activity = (nodeA.active + nodeB.active) / 2;

            ctx.beginPath();
            ctx.moveTo(nodeA.x, nodeA.y);
            ctx.lineTo(nodeB.x, nodeB.y);

            if (activity > 0.01) {
              // Dynamic transition from white to accent
              ctx.strokeStyle = activity > 0.5 
                ? `rgba(204, 255, 0, ${opacity * activity})` 
                : `rgba(255, 255, 255, ${opacity * 0.2})`;
              ctx.lineWidth = 0.5 + (activity * 1.5); // Thicker lines when active
            } else {
              ctx.strokeStyle = `rgba(255, 255, 255, ${opacity * 0.05})`;
              ctx.lineWidth = 0.5;
            }
            ctx.stroke();
          }
        }
      }

      // 3. Render Nodes
      for (const node of nodes) {
        if (node.active > 0.01) {
          const size = 1 + (node.active * 3);

          // Glow
          ctx.beginPath();
          ctx.arc(node.x, node.y, size * 2, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(204, 255, 0, ${node.active * 0.2})`;
          ctx.fill();

          // Core
          ctx.beginPath();
          ctx.arc(node.x, node.y, size * 0.5, 0, Math.PI * 2);
          ctx.fillStyle = accentColor;
          ctx.fill();
        } else {
            // Dormant Star
            ctx.fillStyle = 'rgba(255, 255, 255, 0.1)';
            ctx.fillRect(node.x - 0.5, node.y - 0.5, 1, 1);
        }
      }

      animationFrameId = requestAnimationFrame(draw);
    };

    draw();

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseleave', handleMouseLeave);
      window.removeEventListener('resize', init);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className="fixed inset-0 z-0 bg-dark pointer-events-none">
       {/* Texture Overlay */}
       <div className="absolute inset-0 opacity-[0.04] bg-[url('https://grainy-gradients.vercel.app/noise.svg')] mix-blend-overlay"></div>
       <canvas ref={canvasRef} className="block w-full h-full" />
    </div>
  );
};

