      nodes = [];
      const cols = Math.ceil(width / spacing) + 1;
      const rows = Math.ceil(height / spacing) + 1;

      for (let i = 0; i < cols; i++) {
        for (let j = 0; j < rows; j++) {
          // Add randomness to base grid for "generative" organic feel
          const x = i * spacing + (Math.random() - 0.5) * (spacing * 0.4);
          const y = j * spacing + (Math.random() - 0.5) * (spacing * 0.4);
          nodes.push({
            x,
            y,
            baseX: x,
            baseY: y,
            vx: 0,
            vy: 0,
            active: 0,
            phase: Math.random() * Math.PI * 2
          });
        }
      }
    };

    const handleMouseMove = (e: MouseEvent) => {
      mouse.x = e.clientX;
      mouse.y = e.clientY;
      mouse.active = true;
    };

    const handleMouseLeave = () => {
      mouse.active = false;
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mouseleave', handleMouseLeave);
    window.addEventListener('resize', init);

    init();

    const draw = () => {
      ctx.clearRect(0, 0, width, height);
      time += 0.003; // Slow, ambient time flow

      // 1. Physics Update
      for (const node of nodes) {
        // Subtle ambient breathing movement
        const driftX = Math.sin(time + node.phase) * 1.5;
        const driftY = Math.cos(time + node.phase * 0.8) * 1.5;

        const targetX = node.baseX + driftX;
        const targetY = node.baseY + driftY;

        // Interaction
        if (mouse.active) {
          const dx = mouse.x - node.x;
          const dy = mouse.y - node.y;
          const distSq = dx * dx + dy * dy;

          if (distSq < mouseRadius * mouseRadius) {
            const dist = Math.sqrt(distSq);
            const force = (mouseRadius - dist) / mouseRadius;

            // Gentle Magnetic Pull
            const angle = Math.atan2(dy, dx);
            const pullStrength = force * 0.8;

            node.vx += Math.cos(angle) * pullStrength;
            node.vy += Math.sin(angle) * pullStrength;

            node.active = Math.min(1, node.active + 0.05);
          } else {
            node.active *= 0.95;
          }
        } else {
          node.active *= 0.95;
        }

        // Apply velocities
        node.x += node.vx;
        node.y += node.vy;

        // Return spring - lower strength for floaty feel
        const springStrength = 0.03; 
        node.vx += (targetX - node.x) * springStrength;
        node.vy += (targetY - node.y) * springStrength;

        // Damping
        node.vx *= 0.92;
        node.vy *= 0.92;
      }

      // 2. Render Connections
      ctx.lineWidth = 0.5;
      for (let i = 0; i < nodes.length; i++) {
        const nodeA = nodes[i];

        for (let j = i + 1; j < nodes.length; j++) {
          const nodeB = nodes[j];
          const dx = nodeA.x - nodeB.x;
          const dy = nodeA.y - nodeB.y;
          const distSq = dx * dx + dy * dy;

          if (distSq < connectionLimit * connectionLimit) {
            const dist = Math.sqrt(distSq);
            const opacity = 1 - (dist / connectionLimit);
            const activity = (nodeA.active + nodeB.active) / 2;

            ctx.beginPath();
            ctx.moveTo(nodeA.x, nodeA.y);
            ctx.lineTo(nodeB.x, nodeB.y);

            if (activity > 0.05) {
                // Only highlight highly active connections sparingly
                if (activity > 0.4) {
                     ctx.strokeStyle = `rgba(204, 255, 0, ${opacity * activity * 0.6})`;
                } else {
                     ctx.strokeStyle = `rgba(255, 255, 255, ${opacity * 0.08})`;
                }
            } else {
              // Very faint base web
              ctx.strokeStyle = `rgba(255, 255, 255, ${opacity * 0.03})`;
            }
            ctx.stroke();
          }
        }
      }

      // 3. Render Nodes
      for (const node of nodes) {
        if (node.active > 0.1) {
          const size = 1 + (node.active * 1.5);

          ctx.beginPath();
          ctx.arc(node.x, node.y, size, 0, Math.PI * 2);
          // Highlight active nodes with accent
          ctx.fillStyle = `rgba(204, 255, 0, ${node.active})`;
          ctx.fill();
        } else {
            // Base nodes are extremely subtle
            ctx.fillStyle = 'rgba(255, 255, 255, 0.05)';
            ctx.fillRect(node.x - 0.5, node.y - 0.5, 1, 1);
        }
      }

      animationFrameId = requestAnimationFrame(draw);
    };

    draw();

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseleave', handleMouseLeave);
      window.removeEventListener('resize', init);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className="fixed inset-0 z-0 bg-dark pointer-events-none">
       {/* Texture Overlay */}
       <div className="absolute inset-0 opacity-[0.04] bg-[url('https://grainy-gradients.vercel.app/noise.svg')] mix-blend-overlay"></div>
       <canvas ref={canvasRef} className="block w-full h-full" />
    </div>
  );
};

