import React, { useEffect, useRef } from 'react';

const FluidBackground: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let width = window.innerWidth;
    let height = window.innerHeight;
    let animationFrameId: number;

    // Particle Configuration
    const particles: Particle[] = [];
    const accentColor = '204, 255, 0'; // #CCFF00
    const baseColor = '255, 255, 255';

    class Particle {
      x: number;
      y: number;
      size: number;
      vx: number;
      vy: number;
      life: number;
      maxLife: number;
      isAccent: boolean;
      baseOpacity: number;

      constructor() {
        this.x = Math.random() * width;
        this.y = Math.random() * height;
        // Varied sizes but generally small and subtle
        this.size = Math.random() * 1.5 + 0.5; 

        // Gentle drift velocity
        this.vx = (Math.random() - 0.5) * 0.3; 
        this.vy = (Math.random() - 0.5) * 0.3;

        // Lifecycle for breathing opacity
        this.life = Math.random() * 500;
        this.maxLife = 500 + Math.random() * 500; // Random cycle duration

        // 5% chance for accent color to be "sparing"
        this.isAccent = Math.random() > 0.95; 
        this.baseOpacity = this.isAccent ? 0.5 : 0.15;
      }

      update() {
        this.x += this.vx;
        this.y += this.vy;

        // Wrap around edges seamlessley
        if (this.x < -10) this.x = width + 10;
        if (this.x > width + 10) this.x = -10;
        if (this.y < -10) this.y = height + 10;
        if (this.y > height + 10) this.y = -10;

        this.life++;
      }

      draw() {
        if (!ctx) return;

        // Smooth sine wave fading for "breathing" effect
        // Maps [-1, 1] to [0, 1]
        const cycle = (Math.sin((this.life / this.maxLife) * Math.PI * 2) + 1) / 2;
        const opacity = cycle * this.baseOpacity;

        // Skip drawing if invisible
        if (opacity < 0.01) return;

        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);

        if (this.isAccent) {
            ctx.fillStyle = `rgba(${accentColor}, ${opacity})`;
            // Subtle glow for accent particles
            ctx.shadowBlur = 8;
            ctx.shadowColor = `rgba(${accentColor}, ${opacity * 0.5})`;
        } else {
            ctx.fillStyle = `rgba(${baseColor}, ${opacity})`;
            ctx.shadowBlur = 0;
        }

        ctx.fill();
        ctx.shadowBlur = 0; // Reset for performance
      }
    }

    const init = () => {
      width = window.innerWidth;
      height = window.innerHeight;

      const dpr = window.devicePixelRatio || 1;
      canvas.width = width * dpr;
      canvas.height = height * dpr;
      ctx.scale(dpr, dpr);
      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;

      // Density calculation: fewer particles on smaller screens
      // 1920*1080 / 20000 = ~100 particles
      const area = width * height;
      const count = Math.floor(area / 20000); 

      particles.length = 0;
      for (let i = 0; i < count; i++) {
        particles.push(new Particle());
      }
    };

    const animate = () => {
      ctx.clearRect(0, 0, width, height);

      particles.forEach(p => {
        p.update();
        p.draw();
      });

      animationFrameId = requestAnimationFrame(animate);
    };

    window.addEventListener('resize', init);
    init();
    animate();

    return () => {
      window.removeEventListener('resize', init);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className="fixed inset-0 z-0 bg-dark pointer-events-none">
       {/* Texture Overlay */}
       <div className="absolute inset-0 opacity-[0.04] bg-[url('https://grainy-gradients.vercel.app/noise.svg')] mix-blend-overlay"></div>
       <canvas ref={canvasRef} className="block w-full h-full" />
    </div>
  );
};

export default FluidBackground;

