        <div ref={containerRef} className="max-w-5xl mx-auto relative pb-32">
          {/* Base Line */}
          <div className="absolute left-[20px] md:left-1/2 top-0 bottom-0 w-px md:-translate-x-1/2 z-0">
             <div className="w-full h-full bg-neutral-800" />
          </div>

          {/* Animated Beam */}
          <div className="absolute left-[20px] md:left-1/2 top-0 bottom-0 w-px md:-translate-x-1/2 z-10">
              <motion.div 
                style={{ scaleY }}
                className="w-full h-full bg-accent origin-top shadow-[0_0_15px_rgba(204,255,0,0.6)]"
              />
          </div>

          {steps.map((step, index) => (
             <ProcessStep key={index} step={step} index={index} />
          ))}
        </div>
      </section>
    </div>
  );
};

export default Process;
